contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint256 amount, bytes calldata data) public payable {
        require(address(this).balance >= amount);

        uint256 beforeBalance = address(c).balance;
        uint256 beforeCount = c.depositsCount();

        bool reverted;
        if (caller == address(this)) {
            c.withdrawAll();
            reverted = false;
        } else {
            (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("withdrawAll()"));
            reverted = !ok;
        }

        uint256 afterBalance = address(c).balance;
        uint256 afterCount = c.depositsCount();

        assert(
            caller == address(this)
                ? (afterBalance == beforeBalance - amount && afterCount == beforeCount)
                : (reverted && afterBalance == beforeBalance && afterCount == beforeCount)
        );
    }

    receive() external payable {}
}

