contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Make the test contract the non-owner by taking ownership away
        // (we are the owner by default, so use a different address as caller)
        // We cannot change msg.sender, but we can call from a nested contract.
        // However, we can only interact through c, and msg.sender is this contract.
        // To be a non-owner, deploy a helper? Not allowed. Instead, we rely on the fact
        // that the constructor sets owner = msg.sender = address(this). So we ARE owner.
        // To make a non-owner call, we need another contract. But we can't deploy.
        // So this approach won't work for non-owner unless we have an external caller.
        // The previous rule tries to check non-owner reverts, but we are owner.
        // Let's instead check that a successful owner sendMoney that sends 0 value
        // and empty data to an EOA does not change C's balance or depositsCount.
        // But that's not the same rule.

        // Alternative: the rule is about non-owner. Since we can't be non-owner here,
        // we can't test it. So we must change the rule to something we can test.
        // The accepted rules already cover owner withdraw. We need a different rule.
        // Let's test: For any amount, if the owner calls sendMoney with value > balance,
        // it must revert and leave balance and depositsCount unchanged.
        // That is a general rule.

        uint beforeBalance = address(c).balance;
        uint beforeCount = c.depositsCount();

        // Owner calls sendMoney with value larger than balance to force revert.
        // But we need value > address(c).balance. Use depositAmount as the value.
        // To force revert, require depositAmount > beforeBalance.
        // However, we can't force revert if beforeBalance is huge. We can set a precondition.
        require(depositAmount > beforeBalance);

        // Ensure we have enough Ether to send (we need to send depositAmount)
        // But the call is from c, not from this contract. The value is taken from c's balance.
        // So we don't need to send Ether ourselves; we call c.sendMoney which uses c's balance.
        // But the function is not payable, so we can't send value along with the call.
        // sendMoney is public, not payable, so calling it with value is not allowed.
        // So we cannot send value in the call. The value is taken from c's balance by the contract itself.
        // That's fine: c.sendMoney{value: 0} is allowed, but we want to send value.
        // Wait: sendMoney is not payable, so it cannot receive Ether. But it can send Ether from its balance.
        // The call c.sendMoney(target, value, data) will send value from c's balance to target.
        // The function itself is not payable, so we don't attach value to the call.
        // So we call c.sendMoney(address(this), depositAmount, ""), and it will try to send depositAmount from c to this contract.
        // If depositAmount > c's balance, the inner call will fail, causing sendMoney to revert?
        // Actually, _target.call{value: _value}(_data) will fail if insufficient balance, and since the return value is not checked,
        // the transaction will not revert. The call will just fail silently. The contract does not check the success of the call.
        // So sendMoney will not revert even if the inner call fails. It will just do nothing.
        // And depositsCount and balance will not change (except maybe balance if value=0).
        // So the rule "reverts" is false. The contract does not revert.
        // So we need a different rule.

        // Let's test: For any owner call to sendMoney with value greater than c's balance,
        // the call succeeds (does not revert) and c's balance and depositsCount remain unchanged.
        // Because the inner call fails silently and no state changes.
        // However, if the target is a contract that reverts, the inner call fails, but sendMoney still succeeds.
        // So the general rule: sendMoney never reverts (as long as owner) and never changes depositsCount,
        // and if the inner call fails (e.g., insufficient balance), c's balance is unchanged.
        // But we need a rule that is not trivially true and that a faulty version would break.

        // Let's focus on: sendMoney with value > c's balance does not revert and leaves c's balance unchanged.
        // That is a general rule: for any depositAmount > beforeBalance, calling sendMoney does not revert
        // and afterBalance == beforeBalance and afterCount == beforeCount.
        // However, if sendMoney is called with value > balance, the inner call fails, but the outer function
        // does not revert. So the transaction succeeds. The balance of c remains the same because the inner call failed.
        // depositsCount is unchanged because sendMoney does not touch it.

        // Let's implement that.
        // We need to call c.sendMoney with value = depositAmount, but we must ensure depositAmount > beforeBalance.
        // We already require that.
        // The call: c.sendMoney(address(this), depositAmount, "");
        // This is a top-level call.

        bool reverted;
        try c.sendMoney(address(this), depositAmount, "") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterCount = c.depositsCount();

        assert(!reverted && afterBalance == beforeBalance && afterCount == beforeCount);
    }

    receive() external payable {}
}

