pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C();
    }

    function _run(uint256 depositAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint beforeBalance = address(c).balance;
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        vm.assume(depositAmount > beforeBalance);
        bool reverted;
        try c.sendMoney(address(this), depositAmount, "") {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterBalance = address(c).balance;
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        assertTrue(!reverted && afterBalance == beforeBalance && afterCount == beforeCount);
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}

