        // which causes C's receive fallback to execute when c.sendMoney calls _target with empty data.
        uint afterBal;
        uint afterCount;
        // The deciding call: owner (this test contract) calls c.sendMoney targeting c itself with empty calldata.
        // This triggers c's receive() on c, incrementing depositsCount and increasing c's balance by amount.
        c.sendMoney(address(c), amount, "");
        afterBal = address(c).balance;
        afterCount = c.depositsCount();

        assert(afterBal == beforeBal + amount && afterCount == beforeCount + 1);
    }

    receive() external payable {}
}

